-- LOOSE_EXPERIMENT_NOT_VNG; generated by Studio. Life damage units = per mille.
function GetSkillLevelData(name, data, level)
 if 1 == 0 or level < 1 or level > 10 then return "0,0,0" end
 if name == "enhance_life_rate_damage" then return tostring(10 + (level-1)*10)..",-1,0" end
 if name == "attackspeed_v" then return tostring(1 + (level-1)*1)..",-1,0" end
 return "0,0,0"
end
